import os
tomllib = __import__('tomllib')

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            toml_config = tomllib.load(f)
            config.update(toml_config)
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_key = key[len(env_prefix):].replace('__', '.').lower()
            set_nested(config, nested_key, value)
    return config

def set_nested(d, keys, value):
    keys = keys.split('.')
    for key in keys[:-1]:
        d = d.setdefault(key, {})
    d[keys[-1]] = value

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'a': 1, 'b': 'two'}
    assert load_config(defaults) == defaults

def test_load_toml():
    defaults = {'a': 1, 'b': 'two'}
    toml_content = b'a = 2\nb = "three"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = load_config(defaults, 'config.toml')
    assert config == {'a': 2, 'b': 'three'}
    os.remove('config.toml')

def test_load_env():
    defaults = {'a': 1, 'b': 'two'}
    env = {'APP_A': '3', 'APP_B': 'four'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env)
    assert config == {'a': 3, 'b': 'four'}

def test_load_nested():
    defaults = {'server': {'port': 8080}}
    env = {'APP_SERVER_PORT': '8081'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env)
    assert config == {'server': {'port': 8081}}

def test_coerce_int():
    defaults = {'a': 1}
    env = {'APP_A': '2'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env)
    assert config == {'a': 2}

def test_coerce_float():
    defaults = {'a': 1.0}
    env = {'APP_A': '2.5'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env)
    assert config == {'a': 2.5}

def test_coerce_bool():
    defaults = {'a': True}
    env = {'APP_A': 'false'}
    config = load_config(defaults, env_prefix='APP_', env_mapping=env)
    assert config == {'a': False}

def test_error_missing_default():
    defaults = {}
    env = {'APP_A': '1'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP_', env_mapping=env)

def test_error_invalid_type():
    defaults = {'a': 1}
    env = {'APP_A': 'two'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP_', env_mapping=env)

